      "type": "obligation",
      "quote": "The detailed plan is binding for the entity submitting the application, as well as for the federal, cantonal and communal authorities.",
      "gist": "The detailed plan is legally binding on the applicant and all government levels."
    },
    {
      "type": "claim",
      "quote": "Appeals against decisions taken by the Federal Council within the scope of the sectoral plan procedure are not possible.",
      "gist": "There is no appeal process for Federal Council decisions in this procedure."
    }
  ]
